def check_Consecutive(l):
    if not l:
        return False
    n = len(l)
    min_val = min(l)
    max_val = max(l)
    if max_val - min_val + 1 != n:
        return False
    expected_sum = (min_val + max_val) * n // 2
    return sum(l) == expected_sum

