def is_undulating(n):
    """
    Check whether the given number is undulating.
    An undulating number has at least three digits and its digits alternately rise and fall.
    Example: 132, 352, 121, 1321, 34567... 
    Specifically, the pattern is either: 
        d1 < d2 > d3 < d4 > ...   or   d1 > d2 < d3 > d4 < ...
    If the number has fewer than 3 digits, it cannot be undulating.
    """
    s = str(n)
    if len(s) < 3:
        return False

    # Determine the first relationship (up or down)
    if s[0] < s[1]:
        expected = '>'
    else:
        expected = '<'

    for i in range(1, len(s) - 1):
        if expected == '>':
            if s[i] <= s[i + 1]:
                return False
            expected = '<'
        else:
            if s[i] >= s[i + 1]:
                return False
            expected = '>'

    return True

