def parse_record(line: str) -> Dict[str, object]:
    """
    Parse a record line into a dict.
    - Fields are separated by ";". Empty fields are ignored.
    - A field is either key=value or a bare key, which maps to True.
    - Keys and unquoted values have surrounding whitespace removed.
    - A value may be wrapped in double quotes: inside the quotes ";" is literal, \\" is an escaped
      quote, and the text is kept exactly (no trimming). The quotes themselves are removed.
    - If a key repeats, the later value wins.

    parse_record('name=Ana; city = Lyon') == {"name": "Ana", "city": "Lyon"}
    parse_record('note="a;b"; urgent') == {"note": "a;b", "urgent": True}
    """
    result: Dict[str, object] = {}
    for raw_field in line.split(';'):
        field = raw_field.strip()
        if not field:
            continue
        if field.startswith('"'):
            # quoted value
            end = field.find('"', 1)
            while end != -1:
                escaped = field[1:end].replace('\\"', '"')
                value = escaped
                field = field[end + 1:].strip()
                if field.startswith('"'):
                    # continue quoted part if line continues after a quoted field
                    end = field.find('"', 1)
                else:
                    break
            key_part = field[:end].strip()
            if '=' in key_part:
                key, raw_val = key_part.split('=', 1)
                key = key.strip()
                value = raw_val.strip()
                # re‑insert any remaining part after the closing quote
                if field[end + 1:].strip():
                    # there may be additional fields; we just continue the loop
                    pass
            else:
                key = key_part.strip()
                value = value
            result[key] = value
        else:
            # unquoted field
            if '=' in field:
                key, raw_val = field.split('=', 1)
                key = key.strip()
                value = raw_val.strip()
                result[key] = value
            else:
                # bare key -> True
                result[field] = True
    return result

