def invoice_total(lines, coupon=None):
    if coupon is not None and coupon != "SAVE10":
        raise ValueError("Invalid coupon")
    discount_cents = 0
    total_pre_tax = 0
    for quantity, unit_price, category in lines:
        amount = quantity * unit_price
        if category != "food":
            if coupon == "SAVE10":
                discount_cents = min(discount_cents, 2000)
                amount -= (amount * 10) // 100
            total_pre_tax += amount
    if coupon == "SAVE10":
        discount_cents = min(discount_cents, 2000)
    tax_cents = int((total_pre_tax + discount_cents) * 13 / 100 + 0.5)
    total_with_tax = total_pre_tax + tax_cents
    return int(round(total_with_tax + 0.5))

