def next_Perfect_Square(N):
    """
    Returns the smallest perfect square that is strictly greater than the input integer N.
    If N is not an integer, a ValueError is raised.
    """
    if not isinstance(N, int):
        raise ValueError("Input must be an integer.")
    root = int(N ** 0.5)
    if root * root == N:
        root += 1
    else:
        root += 1
    return root * root

