def babylonian_squareroot(number):
    if number < 0:
        raise ValueError("square root not defined for negative numbers")
    if number == 0 or number == 1:
        return number
    guess = number / 2.0
    while True:
        next_guess = (guess + number / guess) / 2.0
        if abs(guess - next_guess) < 1e-7:
            return next_guess
        guess = next_guess
    return guess

