def cal_sum(n):
    if n <= 0:
        return 0
    dp = [0] * (n + 1)
    dp[1] = 3
    if n >= 2:
        dp[2] = 0
    if n >= 3:
        dp[3] = 2
    for i in range(4, n + 1):
        dp[i] = dp[i - 2] + dp[i - 3]
    return sum(dp)

