def parse_record(line):
    """
    Parse a record line into a dict.
    - Fields are separated by ";". Empty fields are ignored.
    - A field is either key=value or a bare key, which maps to True.
    - Keys and unquoted values have surrounding whitespace removed.
    - A value may be wrapped in double quotes: inside the quotes ";" is literal, \\" is an escaped
      quote, and the text is kept exactly (no trimming). The quotes themselves are removed.
    - If a key repeats, the later value wins.
    """
    result = {}
    fields = [f for f in line.split(";") if f.strip() != ""]
    for field in fields:
        field = field.strip()
        if not field:
            continue
        if "=" in field:
            key_part, value_part = field.split("=", 1)
            key = key_part.strip()
            raw_value = value_part.strip()
            if raw_value.startswith('"') and raw_value.endswith('"'):
                content = raw_value[1:-1]
                i = 0
                unescaped_content = []
                while i < len(content):
                    if content[i] == "\\":
                        i += 1
                        if i < len(content):
                            unescaped_content.append(content[i])
                            i += 1
                    else:
                        unescaped_content.append(content[i])
                        i += 1
                value = "".join(unescaped_content)
            elif raw_value.startswith('"') and not raw_value.endswith('"'):
                value = raw_value[1:]
            else:
                value = raw_value
        else:
            key = field.strip()
            value = True

        result[key] = value
    return result

