def _to_minutes(t):
    h, m = t.split(":")
    return int(h) * 60 + int(m)

def _to_time(m):
    hours = m // 60
    minutes = m % 60
    return f"{hours:02d}:{minutes:02d}"

def merge_shifts(shifts):
    """Each shift is a (start, end) tuple of "HH:MM" strings within one day, with end after start.
    Merge shifts that overlap or touch. Drop merged shifts shorter than 15 minutes.
    Return the merged shifts as (start, end) tuples sorted by start.

    merge_shifts([("09:00", "12:00"), ("11:30", "13:00")]) == [("09:00", "13:00")]
    """
    if not shifts:
        return []
    minutes = [_to_minutes(s) for s in shifts]
    sorted_idx = sorted(range(len(minutes)), key=lambda i: minutes[i])
    sorted_shifts = [shifts[i] for i in sorted_idx]
    sorted_minutes = [minutes[i] for i in sorted_idx]
    merged = []
    cur_start, cur_end = sorted_minutes[0], sorted_minutes[0]
    for s, e in zip(sorted_minutes[1:], sorted_shifts[1:]):
        start_min = _to_minutes(e[0])
        if start_min <= cur_end:
            if start_min > cur_end:
                cur_end = start_min
            cur_end = max(cur_end, _to_minutes(e[1]))
        else:
            if cur_end - cur_start >= 15:
                merged.append(_to_time(cur_start))
            cur_start, cur_end = start_min, _to_minutes(e[1])
    if cur_end - cur_start >= 15:
        merged.append(_to_time(cur_start))
    return merged

