def count_by_week(dates):
    """dates is a list of "YYYY-MM-DD" strings. Return a dict mapping each ISO week, written
    "YYYY-Www" with the ISO week-numbering year and a two-digit week, to the number of dates in it.

    count_by_week(["2026-06-15", "2026-06-16"]) == {"2026-W25": 2}
    """
    import datetime

    def _iso_week_key(date_str):
        # Parse the date
        d = datetime.datetime.strptime(date_str, "%Y-%m-%d")

        # ISO week-year and week number; %G returns the ISO year, %V returns the ISO week number
        week_year = d.strftime("%G")
        week_num = d.strftime("%V")  # two-digit week number
        return f"{week_year}-W{week_num}"

    result = {}
    for date_str in dates:
        key = _iso_week_key(date_str)
        result[key] = result.get(key, 0) + 1
    return result


