    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    for p in range(2, a + 1):
        if not is_prime(p):
            continue
        if a % p != 0:
            continue
        remainder = a // p
        for q in range(p, remainder + 1):
            if not is_prime(q):
                continue
            if remainder % q != 0:
                continue
            r = remainder // q
            if r < q:
                continue
            if is_prime(r):
                return True
    return False

