import math


def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def find_zero(xs: list):
    """
    xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only one zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees a solution.
    >>> round(find_zero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(find_zero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
    """
    if len(xs) % 2 != 0:
        raise ValueError("The length of coefficients list must be even.")

    if not xs:
        raise ValueError("Coefficients list cannot be empty.")

    highest_index = max(i for i, coeff in enumerate(xs) if coeff != 0)
    if highest_index % 2 != 0:
        raise ValueError("The largest non-zero coefficient must be at an even index.")

    a = len(xs) // 2
    coefficients_a = [xs[2 * i] for i in range(a)]
    coefficients_b = [xs[2 * i + 1] for i in range(a)]

    def solve_cubic(ca, cb):
        n = len(ca)
        if n == 1:
            return -cb[0] / ca[0]
        elif n == 2:
            root = -cb[0] / ca[0]
            discriminant = (cb[1] / ca[0]) ** 2 - 4 * (ca[1] / ca[0])
            if discriminant >= 0:
                return (-cb[1] / ca[0] + math.sqrt(discriminant)) / (2 * (ca[1] / ca[0]))
            else:
                return root
        else:
            leading_coeff = ca[-1]
            coeffs_poly = [ca[i] / leading_coeff for i in range(n)]
            coeffs_poly.append(-1.0)
            coeffs_poly.append(-cb[-1] / leading_coeff)

            def eval_poly(coeffs, val):
                result = 0
                for i, c in enumerate(coeffs):
                    result += c * (val ** i)
                return result

            low, high = -1000.0, 1000.0
            for _ in range(100):
                mid = (low + high) / 2
                if eval_poly(coeffs_poly, mid) == 0:
                    return mid
                if eval_poly(coeffs_poly, low) * eval_poly(coeffs_poly, mid) < 0:
                    high = mid
                else:
                    low = mid
            return (low + high) / 2

    root_a = solve_cubic(coefficients_a, coefficients_b)
    return root_a


